                "spec": {
                    "source_table_full_name": f"{full_schema}.{pred_name}",
                    "primary_key_columns": ["date"],
                    "run_triggered": {}
                }
            }
        )
        print(f"Result2: {result2}")
    except Exception as e2:
        print(f"Second attempt failed: {e2}")

